 "content": "def transform(grid):
    """Overlay the two panels separated by a solid divider; mark shared cells."""
    h, w = len(grid), len(grid[0])
    # A solid line divides the two equal-sized panels. The divider can be
    # horizontal or vertical and its color varies between tasks/examples.
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            top, bottom = grid[:r], grid[r + 1:]
            if len(top) == len(bottom) and top:
                return [[2 if a != 0 and b != 0 else 0
                         for a, b in zip(ra, rb)]
                        for ra, rb in zip(top, bottom)]
    for c in range(w):
        if all(grid[r][c] == grid[0][c] and grid[0][c] != 0 for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if c == w - c - 1 and c > 0:
                return [[2 if a != 0 and b != 0 else 0
                         for a, b in zip(ra, rb)]
                        for ra, rb in zip(left, right)]
    raise ValueError("equal panels and solid divider not found")
